import { NextRequest } from 'next/server'
import { backendProductRoute, birthFromChartJson, loadOwnedChart, jsonError } from '@/lib/interpret/backend'
import { HD_COLUMNS } from '@/lib/interpret/sections'

// ─── Embody HD ────────────────────────────────────────────────────────────────
//
// Generated by the backend (/interpret/hd): CLAUDE_SYSTEM.md + CLAUDE_HD.md +
// CLAUDE_CORE_HD.md, HD evidence and conclusion objects, delivery checks.
// The browser supplies only chart_id. Birth data and intake come from the
// caller's own chart row.

export async function POST(request: NextRequest) {
  return backendProductRoute(request, {
    tag:          'interpret-hd',
    entitlements: ['hd_report', 'combined_report'],
    sections:     HD_COLUMNS,
    path:         '/interpret/hd',
    resolve: async ({ supabase, user, chartId }) => {
      if (!chartId) return jsonError('chart_id required', 400)
      const chart = await loadOwnedChart(supabase, user.id, { id: chartId })
      if (!chart) return jsonError('Chart not found', 404)
      const birth = birthFromChartJson(chart.chart_json)
      if (!birth) return jsonError('Chart has no usable birth data', 422)
      const intake = (chart.intake_self as Record<string, unknown> | null) ?? null
      return { row: chart, body: section => ({ birth, section, intake }) }
    },
  })
}
